        "chinese": "好久没下雨了，地里的土干巴巴的。",
        "pinyin": "Hǎojiǔ méi xià yǔ le, dì li de tǔ gānbābā de.",
        "german": "Es hat lange nicht geregnet, die Erde auf dem Feld ist ausgedörrt."
