      {
        "chinese": "我不想喝冷冰冰的水。",
        "pinyin": "Wǒ bù xiǎng hē lěngbīngbīng de shuǐ.",
        "german": "Ich mag kein eiskaltes Wasser trinken."
      },
      {
        "chinese": "他对新同学冷冰冰的。",
        "pinyin": "Tā duì xīn tóngxué lěngbīngbīng de.",
        "german": "Zu den Neuen in der Klasse ist er eiskalt."
      }
